  state "<span class='xsm-title'>app</span>" as nestedParallel_app {
    state "<span class='xsm-title'>navigation</span> <span class='xsm-chip'>on SEARCH → search</span>" as nestedParallel_app_navigation {
      [*] --> nestedParallel_app_navigation_home
      state "<span class='xsm-title'>home</span>" as nestedParallel_app_navigation_home {
        [*] --> nestedParallel_app_navigation_home_feed
        state "<span class='xsm-title'>feed</span>" as nestedParallel_app_navigation_home_feed
        state "<span class='xsm-title'>detail</span>" as nestedParallel_app_navigation_home_detail
      }
      state "<span class='xsm-title'>search</span>" as nestedParallel_app_navigation_search
    }
    state "<span class='xsm-title'>notifications</span>" as nestedParallel_app_notifications {
      direction LR
      [*] --> nestedParallel_app_notifications_idle
      state "<span class='xsm-title'>idle</span>" as nestedParallel_app_notifications_idle
      state "<span class='xsm-title'>showing</span>" as nestedParallel_app_notifications_showing
    }
  }
}
nestedParallel_app_navigation_home_feed --> nestedParallel_app_navigation_home_detail : <span class='xsm-pill'><span class='xsm-ev'>VIEW_POST</span></span>
nestedParallel_app_navigation_home_detail --> nestedParallel_app_navigation_home_feed : <span class='xsm-pill'><span class='xsm-ev'>BACK</span></span>
nestedParallel_app_navigation_search --> nestedParallel_app_navigation_home : <span class='xsm-pill'><span class='xsm-ev'>GO_HOME</span></span>
nestedParallel_app_notifications_idle --> nestedParallel_app_notifications_showing : <span class='xsm-pill'><span class='xsm-ev'>NEW_NOTIFICATION</span></span>
nestedParallel_app_notifications_showing --> nestedParallel_app_notifications_idle : <span class='xsm-pill'><span class='xsm-kw'>after</span> 5000 ms</span>
